from flask import Flask, request, redirect, session, url_for
from urllib.parse import urlparse, urljoin
import secrets
import hashlib
import hmac

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

OAUTH_CLIENT_ID = "app-client-id-prod"
OAUTH_CLIENT_SECRET = "s3cr3t-key-do-not-share"
AUTHORIZATION_ENDPOINT = "https://idp.internal.corp/oauth2/authorize"
TOKEN_ENDPOINT = "https://idp.internal.corp/oauth2/token"

ALLOWED_REDIRECT_DOMAINS = [
    "app.internal.corp",
    "dashboard.internal.corp",
]

def is_safe_redirect(target):
    """Validate redirect URL against allowed domains.
    Uses domain suffix matching for flexibility with subdomains."""
    if not target:
        return False
    parsed = urlparse(target)
    if not parsed.scheme in ('https', 'http', ''):
        return False
    if not parsed.netloc:
        # relative URL, considered safe
        return True
    # Check if the target domain ends with any allowed domain
    for allowed in ALLOWED_REDIRECT_DOMAINS:
        if parsed.netloc.endswith(allowed):
            return True
    return False

@app.route('/oauth/login')
def oauth_login():
    """Initiate OAuth2 authorization code flow."""
    redirect_uri = request.args.get('redirect_uri', url_for('oauth_callback', _external=True))
    next_url = request.args.get('next', '/')

    # Store state for CSRF protection
    state = secrets.token_urlsafe(32)
    session['oauth_state'] = state
    session['post_login_redirect'] = next_url

    auth_url = (
        f"{AUTHORIZATION_ENDPOINT}?"
        f"response_type=code&"
        f"client_id={OAUTH_CLIENT_ID}&"
        f"redirect_uri={redirect_uri}&"
        f"state={state}&"
        f"scope=openid+profile+email"
    )
    return redirect(auth_url)

@app.route('/oauth/callback')
def oauth_callback():
    """Handle OAuth2 callback with authorization code."""
    code = request.args.get('code')
    state = request.args.get('state')

    # Verify state parameter
    if not state or state != session.get('oauth_state'):
        return "Invalid state parameter", 403

    # Exchange code for token (simplified)
    # In production this would call TOKEN_ENDPOINT
    session['authenticated'] = True
    session.pop('oauth_state', None)

    # Redirect to the post-login destination
    next_url = session.pop('post_login_redirect', '/')

    if is_safe_redirect(next_url):
        return redirect(next_url)
    return redirect('/')

@app.route('/oauth/authorize')
def oauth_authorize():
    """Internal authorization endpoint that redirects back to client.
    Accepts redirect_uri from registered clients."""
    redirect_uri = request.args.get('redirect_uri', '')
    client_id = request.args.get('client_id', '')
    response_type = request.args.get('response_type', '')
    state = request.args.get('state', '')

    if not session.get('authenticated'):
        return redirect(url_for('oauth_login', next=request.url))

    # Generate authorization code
    auth_code = secrets.token_urlsafe(32)

    # Vulnerability: redirect_uri is not validated against registered URIs
    # An attacker can supply an arbitrary redirect_uri to steal the auth code
    callback_url = f"{redirect_uri}?code={auth_code}&state={state}"
    return redirect(callback_url)

@app.route('/dashboard')
def dashboard():
    if not session.get('authenticated'):
        return redirect(url_for('oauth_login'))
    return "<h1>Welcome to Dashboard</h1>"

